+/// EXPERIMENT (#3397, not for merge): live driver memory by Vulkan object
+/// type, from `VK_EXT_device_memory_report`.
+#[cfg(all(unix, not(target_vendor = "apple")))]
+pub(crate) mod memory_report {
+    use ash::vk;
+    use std::collections::{BTreeMap, HashMap};
+    use std::sync::{Mutex, OnceLock};
+
+    #[derive(Default)]
+    struct Report {
+        /// Allocation id → (object type, imported, bytes).
+        live: HashMap<u64, (i32, bool, u64)>,
+        /// (object type, imported) → (live bytes, live count, peak bytes).
+        by_type: BTreeMap<(i32, bool), (u64, u64, u64)>,
+        failed: u64,
+    }
+
+    static REPORT: OnceLock<Mutex<Report>> = OnceLock::new();
+
+    pub unsafe extern "system" fn callback(
+        data: *const vk::DeviceMemoryReportCallbackDataEXT<'_>,
+        _: *mut core::ffi::c_void,
+    ) {
+        // SAFETY: the driver passes a valid callback record.
+        let data = unsafe { &*data };
+        let mut report = REPORT.get_or_init(Default::default).lock().expect("report");
+        let ty = data.ty;
+        if ty == vk::DeviceMemoryReportEventTypeEXT::ALLOCATE
+            || ty == vk::DeviceMemoryReportEventTypeEXT::IMPORT
+        {
+            let key = (
+                data.object_type.as_raw(),
+                ty == vk::DeviceMemoryReportEventTypeEXT::IMPORT,
+            );
+            report
+                .live
+                .insert(data.memory_object_id, (key.0, key.1, data.size));
+            let row = report.by_type.entry(key).or_default();
+            row.0 += data.size;
+            row.1 += 1;
+            row.2 = row.2.max(row.0);
+        } else if ty == vk::DeviceMemoryReportEventTypeEXT::FREE
+            || ty == vk::DeviceMemoryReportEventTypeEXT::UNIMPORT
+        {
+            if let Some((object, imported, size)) = report.live.remove(&data.memory_object_id) {
+                let row = report.by_type.entry((object, imported)).or_default();
+                row.0 -= size;
+                row.1 -= 1;
+            }
+        } else {
+            report.failed += data.size;
+        }
+    }
+
+    /// Logs every object type's live bytes, live count and peak bytes.
+    pub fn log(phase: &'static str) {
+        let report = REPORT.get_or_init(Default::default).lock().expect("report");
+        let rows: Vec<(String, bool, u64, u64, u64)> = report
+            .by_type
+            .iter()
+            .map(|(&(object, imported), &(live, count, peak))| {
+                (
+                    format!("{:?}", vk::ObjectType::from_raw(object)),
+                    imported,
+                    live,
+                    count,
+                    peak,
+                )
+            })
+            .collect();
+        let (live, peak): (u64, u64) = report
+            .by_type
+            .values()
+            .filter(|row| row.0 > 0 || row.2 > 0)
+            .fold((0, 0), |(l, p), row| (l + row.0, p + row.2));
+        tracing::debug!(
+            phase,
+            live,
+            peak_sum = peak,
+            failed = report.failed,
+            ?rows,
+            "driver memory report census"
+        );
+    }
+}
